/**
 * Creates a cylinder mesh that connects two points in 3D space.
 */
function createCylinderBeam(point1, point2, radius, name) {
    const direction = new THREE.Vector3().subVectors(point2, point1);
    const length = direction.length();

    const geometry = new THREE.CylinderGeometry(radius, radius, length, 16);
    const mesh = new THREE.Mesh(geometry);
    mesh.name = name;

    const Y_AXIS = new THREE.Vector3(0, 1, 0);
    mesh.quaternion.setFromUnitVectors(Y_AXIS, direction.clone().normalize());
    mesh.position.copy(point1).add(direction.multiplyScalar(0.5));

    return mesh;
}

/**
 * Converts a BufferGeometry to OBJ format string, applying the mesh's world transform.
 */
function geometryToOBJ(mesh) {
    // Update the world matrix
    mesh.updateMatrixWorld(true);

    const geometry = mesh.geometry;
    const position = geometry.getAttribute('position');
    const normal = geometry.getAttribute('normal');
    const index = geometry.index;

    let obj = `# ${mesh.name}\n`;
    obj += `# Vertices: ${position.count}\n`;

    // Transform and write vertices
    for (let i = 0; i < position.count; i++) {
        const vertex = new THREE.Vector3(
            position.getX(i),
            position.getY(i),
            position.getZ(i)
        );
        // Apply the world matrix transformation
        vertex.applyMatrix4(mesh.matrixWorld);
        obj += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    // Transform and write normals (use normal matrix for proper normal transformation)
    if (normal) {
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(mesh.matrixWorld);
        for (let i = 0; i < normal.count; i++) {
            const n = new THREE.Vector3(
                normal.getX(i),
                normal.getY(i),
                normal.getZ(i)
            );
            n.applyMatrix3(normalMatrix).normalize();
            obj += `vn ${n.x.toFixed(6)} ${n.y.toFixed(6)} ${n.z.toFixed(6)}\n`;
        }
    }

    // Write faces
    if (index) {
        for (let i = 0; i < index.count; i += 3) {
            const a = index.getX(i) + 1;
            const b = index.getX(i + 1) + 1;
            const c = index.getX(i + 2) + 1;
            if (normal) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    } else {
        for (let i = 0; i < position.count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (normal) {
                obj += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                obj += `f ${a} ${b} ${c}\n`;
            }
        }
    }

    return obj;
