        const cabinRoofGeometry = new THREE.ConeGeometry(cabinRadius * 1.1, 0.5, 8);
        const cabinRoofMesh = new THREE.Mesh(cabinRoofGeometry);
        cabinRoofMesh.name = `cabin_roof_${i}`;
        cabinRoofMesh.position.y = -cabinSuspensionArmLength - (cabinHeight) + cabinHeight;
        cabinGroup.add(cabinRoofMesh);

        const cabinFloorGeometry = new THREE.CylinderGeometry(cabinRadius, cabinRadius, 0.1, 8);
        const cabinFloorMesh = new THREE.Mesh(cabinFloorGeometry);
        cabinFloorMesh.name = `cabin_floor_${i}`;
        cabinFloorMesh.position.y = -cabinSuspensionArmLength - cabinHeight;
        cabinGroup.add(cabinFloorMesh);
    }

    return root;
}

// Main export logic
const OUTPUT_DIR = '/root/output';
const PART_MESHES_DIR = path.join(OUTPUT_DIR, 'part_meshes');
const LINKS_DIR = path.join(OUTPUT_DIR, 'links');

// Create the scene
const root = createScene();
root.updateMatrixWorld(true);

// Find all top-level parts (Groups directly under root)
const parts = [];
root.children.forEach(child => {
    if (child.isGroup) {
        parts.push(child);
    }
});

console.log(`Found ${parts.length} top-level parts:`);
parts.forEach(p => console.log(`  - ${p.name}`));

// Process each part
for (const part of parts) {
    const partName = part.name;
    const partDir = path.join(PART_MESHES_DIR, partName);

    // Create directory for this part
    fs.mkdirSync(partDir, { recursive: true });

    console.log(`\nProcessing part: ${partName}`);

    // Collect all meshes in this part (direct children and nested in sub-groups)
    const allMeshesInPart = [];

    function collectMeshes(object, meshList) {
        object.children.forEach(child => {
            if (child.isMesh) {
                meshList.push(child);
            } else if (child.isGroup) {
                // For sub-groups (like cabin_0, cabin_1, etc.), collect their meshes too
                collectMeshes(child, meshList);
            }
        });
    }

    // Process direct mesh children and collect all for link file
    part.children.forEach(child => {
        if (child.isMesh) {
            // Direct mesh - save individually
            const meshName = child.name || `mesh_${allMeshesInPart.length}`;
            const objContent = geometryToOBJ(child);
            const filePath = path.join(partDir, `${meshName}.obj`);
            fs.writeFileSync(filePath, objContent);
            console.log(`  Saved: ${meshName}.obj`);
            allMeshesInPart.push(child);
        } else if (child.isGroup) {
            // Sub-group (like cabin_0) - create subdirectory and save each mesh
            const subGroupName = child.name;
            const subGroupDir = path.join(partDir, subGroupName);
            fs.mkdirSync(subGroupDir, { recursive: true });

            child.children.forEach(subChild => {
                if (subChild.isMesh) {
                    const meshName = subChild.name || `mesh`;
                    const objContent = geometryToOBJ(subChild);
                    const filePath = path.join(subGroupDir, `${meshName}.obj`);
                    fs.writeFileSync(filePath, objContent);
                    console.log(`  Saved: ${subGroupName}/${meshName}.obj`);
                    allMeshesInPart.push(subChild);
                }
            });
        }
    });

    // Create combined link file for this part
    if (allMeshesInPart.length > 0) {
        const linkContent = combineMeshesToOBJ(allMeshesInPart, partName);
        const linkPath = path.join(LINKS_DIR, `${partName}.obj`);
        fs.writeFileSync(linkPath, linkContent);
        console.log(`  Created link file: ${partName}.obj`);
    }
}

console.log('\nExport complete!');
